/*
 * A119040  Numbers k such that the k-th triangular number contains only
 *          digits {0,1,5}.
 * https://oeis.org/A119040
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = k such that the k-th triangular number T_k = k*(k+1)/2
 *            contains only digits 0, 1, 5. The sequence is generated by
 *            scanning increasing k and keeping all those that satisfy the
 *            digit condition
 * Range:     u8 n <= 5, u16 n <= 9, u32 n <= 25, u64 n <= 37, u128 n <= 37,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

static seq_t *cache = NULL;          /* array of found k values */
static size_t cache_len = 0;         /* number of stored values */
static size_t cache_cap = 0;         /* current capacity of cache */
static idx_t next_k = 1;             /* next k to test */

/* Check whether a number contains only digits 0,1,5 */
static bool allowed_digits(seq_t v)
{
    if (v == 0) return true;
    while (v != 0) {
        int d = (int)(v % 10);
        if (d != 0 && d != 1 && d != 5) return false;
        v /= 10;
    }
    return true;
}

/* Append a value to the cache, growing it if necessary */
static void cache_append(seq_t val)
{
    if (cache_cap == 0) {
        cache_cap = 16;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else if (cache_len == cache_cap) {
        cache_cap <<= 1;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
    cache[cache_len++] = val;
}

seq_t a(idx_t n)
{
    /* Ensure the cache contains at least n elements */
    while (cache_len < n) {
        /* Keep scanning k until we find enough qualifying k's */
        for (;;) {
            seq_t k = (seq_t)next_k;
            seq_t T = k * (k + 1) / 2;
            if (allowed_digits(T)) {
                cache_append(k);
                ++next_k;
                break;
            }
            ++next_k;
        }
    }
    return cache[n - 1];   /* n is 1‑based */
}
